q = [(0, 0, 0)]
while q:
    cost, u, k = heapq.heappop(q)
    if cost != d[u][k]:
        continue
    for v, w in g[u]:
        for nk, price in [(k, w), (1, w // 2)] if not k else [(k, w)]:
            if cost + price < d[v][nk]:
                d[v][nk] = cost + price
                heapq.heappush(q, (cost + price, v, nk))
