using boost::multiprecision::cpp_int;
using ll = long long;
int main() {
    int n, m;
    cin >> n >> m;
    vector<tuple<int, int, ll>> e;
    vector<vector<int>> r(n);
    while (m--) {
        int a, b;
        ll w;
        cin >> a >> b >> w;
        --a;
        --b;
        e.push_back({a, b, w});
        r[b].push_back(a);
    }
    vector<int> ok(n);
    vector<int> st{n - 1};
    ok[n - 1] = 1;
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        for (int v : r[u])
            if (!ok[v]) {
                ok[v] = 1;
                st.push_back(v);
            }
    }
    const ll neg = LLONG_MIN / 4;
    vector<ll> d(n, neg);
    d[0] = 0;
    for (int i = 0; i < n; i++) {
        bool change = false;
        for (auto [a, b, w] : e)
            if (d[a] != neg && d[a] + w > d[b]) {
                d[b] = d[a] + w;
                change = true;
                if (i == n - 1 && ok[b]) {
                    cout << -1 << '\n';
                    return 0;
                }
            }
        if (!change)
            break;
    }
    cout << d[n - 1] << '\n';
}

