int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    int M = 1;
    for (int &x : a) {
        cin >> x;
        M = max(M, x);
    }
    vector<int> sp(M + 1), ex(M + 1), tau(M + 1), pr;
    tau[1] = 1;
    for (int i = 2; i <= M; i++) {
        if (!sp[i]) {
            sp[i] = i;
            ex[i] = 1;
            tau[i] = 2;
            pr.push_back(i);
        }
        for (int p : pr) {
            if (1LL * i * p > M)
                break;
            int j = i * p;
            sp[j] = p;
            if (p == sp[i]) {
                ex[j] = ex[i] + 1;
                tau[j] = tau[i] / (ex[i] + 1) * (ex[j] + 1);
                break;
            }
            ex[j] = 1;
            tau[j] = tau[i] * 2;
        }
    }
    for (int x : a)
        cout << tau[x] << '\n';
}

#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
ll pw(ll a, ll b, ll m) {
    ll r = 1;
    while (b) {
        if (b & 1)
            r = r * a % m;
        a = a * a % m;
        b >>= 1;
    }
    return r;
}
int main() {
    int n;
    cin >> n;
    while (n--) {
        ll a, b, c;
        cin >> a >> b >> c;
        if (a == 0)
            cout << ((b == 0 && c > 0) ? 1 : 0);
        else
            cout << pw(a, pw(b, c, 1000000006), 1000000007);
        cout << '\n';
    }
}

