#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
const ll P = 1000000007;
ll pw(ll a, ll b) {
    ll r = 1;
    for (; b; b >>= 1, a = a * a % P)
        if (b & 1)
            r = r * a % P;
    return r;
}
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> q(n);
    int M = 0;
    for (auto &[a, b] : q) {
        cin >> a >> b;
        M = max(M, a);
    }
    vector<ll> f(M + 1, 1), g(M + 1, 1);
    for (int i = 1; i <= M; i++)
        f[i] = f[i - 1] * i % P;
    g[M] = pw(f[M], P - 2);
    for (int i = M; i; i--)
        g[i - 1] = g[i] * i % P;
    for (auto [a, b] : q)
        cout << f[a] * g[b] % P * g[a - b] % P << '\n';
}

