#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
vector<ll> dij(vector<vector<pair<int, int>>> &g, int s) {
    vector<ll> d(g.size(), (ll)1e18);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> q;
    d[s] = 0;
    q.push({0, s});
    while (!q.empty()) {
        auto [a, u] = q.top();
        q.pop();
        if (a != d[u])
            continue;
        for (auto [v, w] : g[u])
            if (a + w < d[v]) {
                d[v] = a + w;
                q.push({d[v], v});
            }
    }
    return d;
}
int main() {
    int n, a, b;
    cin >> n >> a >> b;
    vector<vector<pair<int, int>>> A(n), B(n);
    for (auto [g, m] :
         vector<pair<vector<vector<pair<int, int>>> *, int>>{{&A, a}, {&B, b}})
        while (m--) {
            int u, v, w;
            cin >> u >> v >> w;
            (*g)[u].push_back({v, w});
            (*g)[v].push_back({u, w});
        }
    int s, t;
    cin >> s >> t;
    auto as = dij(A, s), at = dij(A, t), bs = dij(B, s), bt = dij(B, t);
    ll ans = LLONG_MAX;
    for (int v = 0; v < n; v++)
        ans = min({ans, as[v] + bt[v], bs[v] + at[v]});
    cout << ans << '\n';
}

