    vector<vector<pair<int, int>>> g(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back({v, i});
        g[v].push_back({u, i});
    }
    vector<int> t(n, -1), low(n), sz(n);
    int timer = 0;
    ll ans = 0;
    function<void(int, int)> dfs = [&](int u, int pe) {
        t[u] = low[u] = timer++;
        sz[u] = 1;
        for (auto [v, id] : g[u]) {
            if (id == pe)
                continue;
            if (t[v] < 0) {
                dfs(v, id);
                sz[u] += sz[v];
                low[u] = min(low[u], low[v]);
                if (low[v] > t[u])
                    ans = max(ans, 1LL * sz[v] * (n - sz[v]));
            } else
                low[u] = min(low[u], t[v]);
        }
    };
    dfs(0, -1);
    cout << ans << '\n';
}

