    string s;
    for (int a = 0; a < 3; a++) {
        getline(cin, s);
        stringstream ss(s);
        int x;
        while (ss >> x) {
            p[x] = a;
            n = max(n, x);
        }
    }
    auto show = [&]() {
        cout << step;
        for (int a = 0; a < 3; a++) {
            cout << ' ' << char('A' + a) << '(';
            bool first = true;
            for (int k = n; k; k--)
                if (p[k] == a) {
                    if (!first)
                        cout << ' ';
                    first = false;
                    cout << k;
                }
            cout << ')';
        }
        cout << '\n';
    };
    function<void(int, int)> go = [&](int k, int t) {
        if (!k)
            return;
        if (p[k] == t) {
            go(k - 1, t);
            return;
        }
        int u = 3 - p[k] - t;
        go(k - 1, u);
        p[k] = t;
        step++;
        show();
        go(k - 1, t);
    };
    show();
    go(n, 2);
}

