    for (size_t k = 0; k < s.size(); k++)
        if (s[k] == ';' || s[k] == '.') {
            string line = s.substr(start, k - start);
            start = k + 1;
            if (line.empty())
                continue;
            char name = line[0];
            string e = line.substr(2);
            cpp_int sum = 0, prod = 1;
            size_t b = 0;
            for (size_t j = 0; j <= e.size(); j++)
                if (j == e.size() || e[j] == '+' || e[j] == '*') {
                    string t = e.substr(b, j - b);
                    cpp_int x;
                    if (t.size() == 1 && isalpha(t[0]))
                        x = v[t[0]];
                    else {
                        x = 0;
                        int sign = 1;
                        size_t h = 0;
                        if (t[0] == '-') {
                            sign = -1;
                            h = 1;
                        } else if (t[0] == '+')
                            h = 1;
                        for (; h < t.size(); h++)
                            x = x * 10 + t[h] - '0';
                        x *= sign;
                    }
                    prod *= x;
                    if (j == e.size() || e[j] == '+') {
                        sum += prod;
                        prod = 1;
                    }
                    b = j + 1;
                }
            v[name] = sum;
            cout << name << " = " << sum << '\n';
        }
}

