cpp_int pw(cpp_int a, cpp_int e, cpp_int m) {
    cpp_int r = 1;
    while (e > 0) {
        if ((e & 1) != 0)
            r = r * a % m;
        a = a * a % m;
        e >>= 1;
    }
    return r;
}
