    for (cpp_int q = 2; q * q <= x; q++)
        if (x % q == 0) {
            f.push_back(q);
            while (x % q == 0)
                x /= q;
        }
    if (x > 1)
        f.push_back(x);
    vector<cpp_int> a;
    for (cpp_int g = 1; g < p; g++) {
        bool ok = true;
        for (auto q : f)
            if (pw(g, (p - 1) / q, p) == 1) {
                ok = false;
                break;
            }
        if (ok)
            a.push_back(g);
    }
    for (int i = 0; i < (int)a.size(); i++)
