int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int V = n * n;
    vector<int> w(V);
    for (int &x : w)
        cin >> x;
    vector<vector<int>> g(V);
    for (int u = 0; u < V; u++)
        for (int v : {u - n, u + n, u - 1, u + 1})
            if (v >= 0 && v < V && (abs(v - u) == n || v / n == u / n))
                g[u].push_back(v);
    map<int, vector<int>> cache;
    int q;
    cin >> q;
    while (q--) {
        int a, b, c, e;
        cin >> a >> b >> c >> e;
        int s = (a - 1) * n + b - 1, t = (c - 1) * n + e - 1;
        if (!cache.count(s)) {
            vector<int> d(2 * V, INT_MAX);
            using P = pair<int, int>;
            priority_queue<P, vector<P>, greater<P>> pq;
            d[2 * s] = w[s];
            d[2 * s + 1] = 0;
            pq.push({w[s], 2 * s});
            pq.push({0, 2 * s + 1});
            auto upd = [&](int v, int cost) {
                if (cost < d[v]) {
                    d[v] = cost;
                    pq.push({cost, v});
                }
            };
            while (!pq.empty()) {
                auto [cost, z] = pq.top();
                pq.pop();
                if (cost != d[z])
                    continue;
                int u = z / 2, k = z % 2;
                for (int v : g[u]) {
                    upd(2 * v + k, cost + w[v]);
                    if (!k)
                        upd(2 * v + 1, cost);
                }
            }
            vector<int> ans(V);
            for (int i = 0; i < V; i++)
                ans[i] = min(d[2 * i], d[2 * i + 1]);
            cache[s] = move(ans);
        }
        cout << cache[s][t] << '\n';
    }
}

