#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
struct Pt {
    cpp_int x, y;
    bool operator<(const Pt &b) const {
        return x != b.x ? x < b.x : y < b.y;
    }
    bool operator==(const Pt &b) const {
        return x == b.x && y == b.y;
    }
};
cpp_int cross(Pt a, Pt b, Pt c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}
vector<Pt> hull(vector<Pt> a) {
    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());
    if (a.size() < 3)
        return a;
    vector<Pt> h;
    for (Pt p : a) {
        while (h.size() > 1 && cross(h[h.size() - 2], h.back(), p) <= 0)
            h.pop_back();
        h.push_back(p);
    }
    size_t l = h.size();
    for (int i = (int)a.size() - 2; i >= 0; i--) {
        Pt p = a[i];
        while (h.size() > l && cross(h[h.size() - 2], h.back(), p) <= 0)
            h.pop_back();
        h.push_back(p);
    }
    h.pop_back();
    return h;
}
int main() {
    int n;
    cin >> n;
    vector<Pt> a(n);
    for (auto &p : a)
        cin >> p.x >> p.y;
    auto h = hull(a);
    cpp_int sum = 0;
    for (int i = 0; i < (int)h.size(); i++) {
        Pt p = h[i], q = h[(i + 1) % h.size()];
        sum += p.x * q.y - p.y * q.x;
    }
    if (sum < 0)
        sum = -sum;
    cout << (sum + 1) / 2 << '\n';
}

