int main() {
    string s;
    cin >> s;
    struct S {
        array<int, 10> to;
        int link = -1, len = 0, first = 0, cnt = 0;
        S() {
            to.fill(-1);
        }
    };
    vector<S> a(1);
    int last = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        int c = s[i] - 'a', cur = a.size();
        a.push_back(S());
        a[cur].len = a[last].len + 1;
        a[cur].first = i;
        a[cur].cnt = 1;
        int p = last;
        while (p != -1 && a[p].to[c] < 0) {
            a[p].to[c] = cur;
            p = a[p].link;
        }
        if (p == -1)
            a[cur].link = 0;
        else {
            int q = a[p].to[c];
            if (a[p].len + 1 == a[q].len)
                a[cur].link = q;
            else {
                int clone = a.size();
                a.push_back(a[q]);
                a[clone].len = a[p].len + 1;
                a[clone].cnt = 0;
                while (p != -1 && a[p].to[c] == q) {
                    a[p].to[c] = clone;
                    p = a[p].link;
                }
                a[q].link = a[cur].link = clone;
            }
        }
        last = cur;
    }
    vector<int> count(s.size() + 1), order(a.size());
    for (auto z : a)
        count[z.len]++;
    partial_sum(count.begin(), count.end(), count.begin());
    for (int i = 0; i < (int)a.size(); i++)
        order[--count[a[i].len]] = i;
    for (int k = (int)order.size() - 1; k > 0; k--) {
        int v = order[k];
        a[a[v].link].cnt += a[v].cnt;
    }
    int v = 0;
    for (int i = 1; i < (int)a.size(); i++)
        if (a[i].cnt >= 2 && a[i].len > a[v].len)
            v = i;
    cout << s.substr(a[v].first - a[v].len + 1, a[v].len) << '\n';
}

