        array<ll, 8> d{};
        d[0] = 1;
        for (int c = 0; c < n; c++) {
            array<ll, 8> e{};
            function<void(int, int, ll)> fill = [&](int mask, int next, ll count) {
                int r = 0;
                while (r < 3 && (mask >> r & 1))
                    r++;
                if (r == 3) {
                    e[next] += count;
                    return;
                }
                if (r + 1 < 3 && !(mask >> (r + 1) & 1))
                    fill(mask | (3 << r), next, count);
                if (c + 1 < n)
                    fill(mask | (1 << r), next | (1 << r), count);
            };
            for (int m = 0; m < 8; m++)
                if (d[m]) {
                    if (c == 0 && (m & 1))
                        continue;
                    fill(m | (c == 0 ? 1 : 0), 0, d[m]);
                }
            d = e;
        }
        cout << d[0] << '\n';
    }
}

