using ll = long long;
int main() {
    int M, N, T, ds = 0;
    while (cin >> M >> N >> T && (M || N || T)) {
        vector<string> a(M, string(N, '0'));
        for (auto &r : a)
            for (char &c : r)
                cin >> c;
        cout << "Data Set " << ++ds << ":\n";
        for (int task = 1; task <= T; task++) {
            int X, Y, P;
            char D;
            cin >> X >> Y >> D >> P;
            vector<pair<int, int>> goal(P);
            for (auto &[r, c] : goal) {
                int x, y;
                cin >> x >> y;
                r = M - y;
                c = x - 1;
            }
            int sr = M - Y, sc = X - 1, dir = string("ESWN").find(D);
            int ans = -1;
            if (a[sr][sc] == '0') {
                auto advance = [&](int r, int c, int k) {
                    while (k < P && goal[k] == make_pair(r, c))
                        k++;
                    return k;
                };
                auto id = [&](int r, int c, int d, int k) {
                    return (((k * M + r) * N + c) * 4 + d);
                };
                vector<int> dist((P + 1) * M * N * 4, -1);
                queue<array<int, 4>> q;
                int k = advance(sr, sc, 0);
                q.push({sr, sc, dir, k});
                dist[id(sr, sc, dir, k)] = 0;
                int dr[] = {0, 1, 0, -1}, dc[] = {1, 0, -1, 0};
                while (!q.empty()) {
                    auto z = q.front();
                    q.pop();
                    auto [r, c, d, k] = z;
                    int t = dist[id(r, c, d, k)];
                    if (k == P) {
                        ans = t;
                        break;
                    }
                    for (int op = 0; op < 3; op++) {
                        int nr = r, nc = c, nd = d;
                        if (op == 0) {
                            nr += dr[d];
                            nc += dc[d];
                        } else
                            nd = (d + (op == 1 ? 1 : 3)) % 4;
                        if (nr < 0 || nr >= M || nc < 0 || nc >= N || a[nr][nc] == '1')
                            continue;
                        int nk = advance(nr, nc, k), v = id(nr, nc, nd, nk);
                        if (dist[v] < 0) {
                            dist[v] = t + 1;
                            q.push({nr, nc, nd, nk});
                        }
                    }
                }
            }
            cout << "Task " << task << ": " << ans << '\n';
        }
    }
}

