#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
cpp_int gc(cpp_int a, cpp_int b) {
    while (b != 0) {
        cpp_int r = a % b;
        a = b;
        b = r;
    }
    return a;
}
cpp_int inv(cpp_int a, cpp_int m) {
    cpp_int b = m, x = 1, y = 0;
    while (b != 0) {
        cpp_int q = a / b, r = a - q * b;
        a = b;
        b = r;
        r = x - q * y;
        x = y;
        y = r;
    }
    x %= m;
    if (x < 0)
        x += m;
    return x;
}
cpp_int ceildiv(cpp_int a, cpp_int b) {
    return (a + b - 1) / b;
}
int main() {
    int q;
    cin >> q;
    while (q--) {
        cpp_int x, y, z;
        cin >> x >> y >> z;
        if (x <= 0 || y <= 0 || z <= 0 || z > max(x, y)) {
            cout << -1 << '\n';
            continue;
        }
        cpp_int g = gc(x, y);
        if (z % g != 0) {
            cout << -1 << '\n';
            continue;
        }
        x /= g;
        y /= g;
        z /= g;
        if (z == x || z == y) {
            cout << 1 << '\n';
            continue;
        }
        cpp_int best = -1;
        for (int dir = 0; dir < 2; dir++) {
            cpp_int a = dir ? y : x, b = dir ? x : y;
            cpp_int n0 = b == 1 ? cpp_int(1) : cpp_int((z * inv(a % b, b)) % b);
            if (n0 == 0)
                n0 = b;
            for (int mode = 0; mode < 2; mode++) {
                if ((mode == 0 && z >= b) || (mode == 1 && z >= a))
                    continue;
                cpp_int target = z;
                if (mode)
                    target += b;
                cpp_int n = n0, need = ceildiv(target, a);
                if (n < need)
                    n += ceildiv(need - n, b) * b;
                cpp_int m = (n * a - target) / b, steps = 2 * (n + m);
                if (best < 0 || steps < best)
                    best = steps;
            }
        }
        cout << best << '\n';
    }
}

