    return (neg ? "-" : "") + s;
}
vector<pair<int, Q>> parse(string s) {
    vector<pair<int, Q>> v;
    size_t p = 0;
    while ((p = s.find('<', p)) != string::npos) {
        size_t q = s.find(',', p), e = s.find('>', q);
        string t = s.substr(q + 1, e - q - 1);
        t.erase(remove_if(t.begin(), t.end(),
                          [](char c) { return isspace((unsigned char)c); }),
                t.end());
        v.push_back({stoi(s.substr(p + 1, q - p - 1)), dec(t)});
        p = e + 1;
    }
    return v;
}
