    string s, t;
    getline(cin, s);
    getline(cin, t);
    auto a = parse(s), b = parse(t);
    int i = 0, j = 0;
    vector<pair<int, Q>> v;
    Q total(0);
    while (i < (int)a.size() && j < (int)b.size()) {
        Q w = min(a[i].second, b[j].second);
        v.push_back({a[i].first - b[j].first, w});
        total += w;
        a[i].second -= w;
        b[j].second -= w;
        if (a[i].second == 0)
            i++;
        if (b[j].second == 0)
            j++;
    }
    sort(v.begin(), v.end(), [](auto a, auto b) { return a.first < b.first; });
    Q sum(0);
    int med = 0;
    for (auto [d, w] : v) {
        sum += w;
        if (2 * sum >= total) {
            med = d;
            break;
        }
    }
    Q ans(0);
    for (auto [d, w] : v)
        ans += abs(d - med) * w;
    cout << ans.numerator() << '/' << ans.denominator() << '\n';
}

