#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
cpp_int gc(cpp_int a, cpp_int b) {
    while (b != 0) {
        cpp_int r = a % b;
        a = b;
        b = r;
    }
    return a;
}
cpp_int inv(cpp_int a, cpp_int m) {
    cpp_int b = m, x = 1, y = 0;
    while (b != 0) {
        cpp_int q = a / b, r = a - q * b;
        a = b;
        b = r;
        r = x - q * y;
        x = y;
        y = r;
    }
    x %= m;
    if (x < 0)
        x += m;
    return x;
}
cpp_int ceildiv(cpp_int a, cpp_int b) {
    return (a + b - 1) / b;
}
int main() {
    int n;
    cin >> n;
    vector<pair<cpp_int, int>> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i].first;
        a[i].second = i;
    }
    cpp_int S;
    cin >> S;
    sort(a.rbegin(), a.rend());
    vector<cpp_int> g(n + 1), counts(n);
    for (int i = n - 1; i >= 0; i--)
        g[i] = gc(g[i + 1], a[i].first);
    cpp_int best = -1;
    set<vector<cpp_int>> ans;
    auto record = [&](cpp_int used) {
        vector<cpp_int> v(n);
        for (int j = 0; j < n; j++)
            v[a[j].second] = counts[j];
        if (best < 0 || used < best) {
            best = used;
            ans.clear();
        }
        if (used == best)
            ans.insert(v);
    };
    function<void(int, cpp_int, cpp_int)> dfs = [&](int i, cpp_int rem, cpp_int used) {
        if (rem == 0) {
            for (int j = i; j < n; j++)
                counts[j] = 0;
            record(used);
            return;
        }
        if (i == n || rem % g[i] != 0 ||
            (best >= 0 && used + ceildiv(rem, a[i].first) > best))
            return;
        if (i == n - 1) {
            if (rem % a[i].first == 0) {
                counts[i] = rem / a[i].first;
                record(used + counts[i]);
            }
            return;
        }
        if (i == n - 2) {
            cpp_int A = a[i].first, B = a[i + 1].first, G = gc(A, B);
            if (rem % G != 0)
                return;
            cpp_int step = B / G, q0 = 0;
            if (step != 1)
                q0 = (rem / G * inv((A / G) % step, step)) % step;
            cpp_int top = rem / A;
            if (q0 > top)
                return;
            cpp_int q = q0 + (top - q0) / step * step;
            counts[i] = q;
            counts[i + 1] = (rem - q * A) / B;
            record(used + counts[i] + counts[i + 1]);
            return;
        }
        cpp_int G = gc(a[i].first, g[i + 1]);
        if (rem % G != 0)
            return;
        cpp_int step = g[i + 1] / G, q0 = 0;
        if (step != 1)
            q0 = (rem / G * inv((a[i].first / G) % step, step)) % step;
        cpp_int top = rem / a[i].first;
        if (q0 > top)
            return;
        cpp_int q = q0 + (top - q0) / step * step;
        for (; q >= 0; q -= step) {
            cpp_int rest = rem - q * a[i].first;
            if (best >= 0 && used + q + ceildiv(rest, a[i + 1].first) > best)
                break;
            counts[i] = q;
            dfs(i + 1, rest, used + q);
        }
    };
    dfs(0, S, 0);
    if (best < 0)
        cout << 0 << '\n';
    else {
        cout << ans.size() << '\n' << best << '\n';
        for (auto v : ans) {
            for (int i = 0; i < n; i++)
                cout << (i ? " " : "") << v[i];
            cout << '\n';
        }
    }
}

