    for (int mask = 0; mask < 1024; mask++)
        if (__builtin_popcount((unsigned)mask) == n) {
            bool ok = true;
            for (auto [cm, k] : tot)
                if (__builtin_popcount((unsigned)(mask & cm)) != k) {
                    ok = false;
                    break;
                }
            if (!ok)
                continue;
            if (U == 1) {
                map<pair<int, int>, ll> memo;
                function<ll(int, int)> go = [&](int used, int hits) {
                    int pos = __builtin_popcount((unsigned)used);
                    if (hits > want[0] || hits + n - pos < want[0])
                        return 0LL;
                    if (pos == n)
                        return (ll)(hits == want[0]);
                    auto key = make_pair(used, hits);
                    if (memo.count(key))
                        return memo[key];
                    ll sum = 0;
                    for (int d = 0; d < 10; d++)
                        if ((mask >> d & 1) && !(used >> d & 1))
                            sum +=
                                go(used | (1 << d), hits + (guess[0][pos] - '0' == d));
                    return memo[key] = sum;
                };
                answer += go(0, 0);
                continue;
            }
            vector<int> hits(U);
            function<void(int, int)> dfs = [&](int pos, int used) {
                if (pos == n) {
                    answer++;
                    return;
                }
                for (int d = 0; d < 10; d++)
                    if ((mask >> d & 1) && !(used >> d & 1)) {
                        int nu = used | (1 << d);
                        bool good = true;
                        for (int c = 0; c < U; c++) {
                            int now = hits[c] + (guess[c][pos] - '0' == d),
                                possible = 0;
                            for (int j = pos + 1; j < n; j++) {
                                int q = guess[c][j] - '0';
                                if ((mask >> q & 1) && !(nu >> q & 1))
                                    possible++;
                            }
                            if (now > want[c] || now + possible < want[c]) {
                                good = false;
                                break;
                            }
                        }
                        if (!good)
                            continue;
                        for (int c = 0; c < U; c++)
                            hits[c] += guess[c][pos] - '0' == d;
                        dfs(pos + 1, nu);
                        for (int c = 0; c < U; c++)
                            hits[c] -= guess[c][pos] - '0' == d;
                    }
            };
            dfs(0, 0);
        }
