    s = str(raw).zfill(n)
    guess = tuple(map(int, s))
    mask = sum(1 << d for d in guess)
    if guess in constraints and constraints[guess] != (A, B):
        bad = True
    if mask in totals and totals[mask] != A + B:
        bad = True
    constraints[guess] = (A, B)
    totals[mask] = A + B
if bad:
    print(0)
    sys.exit()
clues = [(g, v[0]) for g, v in constraints.items()]
answer = 0
zero_allowed = [1023] * n
for guess, want in clues:
    if want == 0:
        for pos, digit in enumerate(guess):
            zero_allowed[pos] &= ~(1 << digit)
clues = [(g, want) for g, want in clues if want > 0]
for digits in itertools.combinations(range(10), n):
    mask = sum(1 << d for d in digits)
    if any((mask & cm).bit_count() != k for cm, k in totals.items()):
        continue
    if not clues:

        @functools.lru_cache(None)
        def zero_count(used):
            pos = used.bit_count()
            if pos == n:
                return 1
            return sum(
                zero_count(used | 1 << d)
                for d in digits
                if not used >> d & 1 and zero_allowed[pos] >> d & 1
            )

        answer += zero_count(0)
        continue
    if len(clues) == 1:
        guess, want = clues[0]

        @functools.lru_cache(None)
        def single(used, hits):
            pos = used.bit_count()
            if hits > want or hits + n - pos < want:
                return 0
            if pos == n:
                return int(hits == want)
            return sum(
                single(used | 1 << d, hits + (guess[pos] == d))
                for d in digits
                if not used >> d & 1 and zero_allowed[pos] >> d & 1
            )

        answer += single(0, 0)
        continue
    hits = [0] * len(clues)

    def dfs(pos, used):
        global answer
        if pos == n:
            answer += 1
            return
        for d in digits:
            if used >> d & 1 or not zero_allowed[pos] >> d & 1:
                continue
            nu = used | 1 << d
            good = True
            for c, (g, want) in enumerate(clues):
                now = hits[c] + (g[pos] == d)
                possible = sum(
                    bool(mask >> q & 1) and not nu >> q & 1 for q in g[pos + 1 :]
                )
                if now > want or now + possible < want:
                    good = False
                    break
            if not good:
                continue
            for c, (g, want) in enumerate(clues):
                hits[c] += g[pos] == d
            dfs(pos + 1, nu)
            for c, (g, want) in enumerate(clues):
                hits[c] -= g[pos] == d

    dfs(0, 0)
