using Shape = vector<pair<int, int>>;
Shape norm(Shape a) {
    int x = INT_MAX, y = INT_MAX;
    for (auto p : a) {
        x = min(x, p.first);
        y = min(y, p.second);
    }
    for (auto &p : a) {
        p.first -= x;
        p.second -= y;
    }
    sort(a.begin(), a.end());
    return a;
}
int main() {
    int n;
    cin >> n;
    string line;
    getline(cin, line);
    vector<set<Shape>> all(n);
    vector<int> area(n);
    for (int i = 0; i < n; i++) {
        getline(cin, line);
        stringstream ss(line);
        int h, x = 0;
        Shape a;
        while (ss >> h) {
            for (int y = 0; y < h; y++)
                a.push_back({x, y});
            x++;
        }
        area[i] = a.size();
        for (int flip = 0; flip < 2; flip++)
            for (int rot = 0; rot < 4; rot++) {
                Shape b;
                for (auto [u, v] : a) {
                    if (flip)
                        u = -u;
                    for (int r = 0; r < rot; r++) {
                        int t = u;
                        u = -v;
                        v = t;
                    }
                    b.push_back({u, v});
                }
                all[i].insert(norm(b));
            }
    }
    int ans = 0;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++) {
            int total = area[i] + area[j];
            if (total <= ans)
                continue;
            bool ok = false;
            for (int order = 0; order < 2 && !ok; order++) {
                int u = order ? j : i, v = order ? i : j;
                for (auto a : all[u]) {
                    if (!binary_search(a.begin(), a.end(), make_pair(0, 0)))
                        continue;
                    int w = 0, h = 0;
                    for (auto [x, y] : a) {
                        w = max(w, x + 1);
                        h = max(h, y + 1);
                    }
                    for (int W = w; W <= total; W++)
                        if (total % W == 0) {
                            int H = total / W;
                            if (H < h)
                                continue;
                            Shape complement;
                            for (int x = 0; x < W; x++)
                                for (int y = 0; y < H; y++)
                                    if (!binary_search(a.begin(), a.end(),
                                                       make_pair(x, y)))
                                        complement.push_back({x, y});
                            if (all[v].count(norm(complement))) {
                                ok = true;
                                break;
                            }
                        }
                    if (ok)
                        break;
                }
            }
            if (ok)
                ans = total;
        }
    cout << ans << '\n';
}

