#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;
int pop(cpp_int z) {
    vector<unsigned long long> w;
    export_bits(z, back_inserter(w), 64);
    int n = 0;
    for (auto x : w)
        n += __builtin_popcountll(x);
    return n;
}
int main() {
    int n, m;
    cin >> n >> m;
    if (min(n, m) == 1) {
        cout << 1 << '\n';
        return 0;
    }
    int B = n * m;
    cpp_int full = (cpp_int(1) << B) - 1;
    vector<cpp_int> row(n), col(m), d1(n + m - 1), d2(n + m - 1), cover(B);
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++) {
            cpp_int bit = cpp_int(1) << (r * m + c);
            row[r] |= bit;
            col[c] |= bit;
            d1[r + c] |= bit;
            d2[r - c + m - 1] |= bit;
        }
    int maxc = 0;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++) {
            int q = r * m + c;
            cover[q] = row[r] | col[c] | d1[r + c] | d2[r - c + m - 1];
            maxc = max(maxc, pop(cover[q]));
        }
    cpp_int avail = full;
    int upper = 0;
    while (avail != 0) {
        int q = boost::multiprecision::lsb(avail);
        upper++;
        avail &= full ^ cover[q];
    }
    function<bool(cpp_int, cpp_int, int)> dfs = [&](cpp_int av, cpp_int cov, int left) {
        cpp_int missing = full ^ cov;
        if (missing == 0)
            return true;
        if (left == 0 || pop(missing) > left * maxc)
