def trim(p):
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p


def ev(p, x):
    s = Q(0)
    for a in reversed(p):
        s = s * x + a
    return s


def deriv(p):
    return trim([i * p[i] for i in range(1, len(p))] or [Q(0)])


def mul(p, q):
    r = [Q(0)] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            r[i + j] += a * b
    return trim(r)


def divmodpoly(p, q):
    p = p.copy()
    out = [Q(0)] * max(1, len(p) - len(q) + 1)
    while p != [0] and len(p) >= len(q):
        k = len(p) - len(q)
        t = p[-1] / q[-1]
        out[k] = t
        for j, a in enumerate(q):
            p[j + k] -= t * a
        trim(p)
    return trim(out), p


def gcdpoly(p, q):
    while q != [0]:
        p, q = q, divmodpoly(p, q)[1]
    return [a / p[-1] for a in p]


def squarefree(p):
    if len(p) == 1:
        return p
    p = divmodpoly(p, gcdpoly(p, deriv(p)))[0]
    return [x / p[-1] for x in p]


def sturm(p):
    s = [p]
    d = deriv(p)
    if d == [0]:
        return s
    s.append(d)
    while True:
        r = divmodpoly(s[-2], s[-1])[1]
        if r == [0]:
            return s
        s.append([-x for x in r])


def variation(s, x):
    signs = [(v > 0) - (v < 0) for p in s if (v := ev(p, x)) != 0]
    return sum(a != b for a, b in zip(signs, signs[1:]))


def roots(s, a, b):
    return variation(s, a) - variation(s, b) - int(ev(s[0], b) == 0) if a < b else 0


def resultant(p, q):
    fac = Q(1)
    while len(q) > 1:
        if p == [0]:
            return Q(0)
        m, n = len(p) - 1, len(q) - 1
        if m < n:
            if m * n % 2:
                fac = -fac
            p, q = q, p
            continue
        r = divmodpoly(p, q)[1]
        if r == [0]:
            return Q(0)
        fac *= q[-1] ** (m - len(r) + 1)
        if m * n % 2:
            fac = -fac
        p, q = q, r
    return fac * q[0] ** (len(p) - 1)


def interpolate(v):
    out = [Q(0)]
    basis = [Q(1)]
    for k in range(len(v)):
        out.extend([Q(0)] * max(0, len(basis) - len(out)))
        for j, x in enumerate(basis):
            out[j] += v[0] * x
        v = [b - a for a, b in zip(v, v[1:])]
        basis = [x / (k + 1) for x in mul(basis, [Q(-k), Q(1)])]
    return trim(out)


def linear(p, a, b):
    r = [Q(0)]
    for x in reversed(p):
        r = mul(r, [b, a])
        r[0] += x
    return trim(r)


def valuepoly(p, F):
    values = []
    for k in range(len(p)):
        q = F.copy()
        q[0] -= k
        values.append(resultant(p, trim(q)))
    return squarefree(interpolate(values))


def sumpoly(p, q):
    return squarefree(
        interpolate(
            [
                resultant(p, linear(q, Q(-1), Q(k)))
                for k in range((len(p) - 1) * (len(q) - 1) + 1)
            ]
        )
    )


def denbound(p):
    L = math.lcm(*(x.denominator for x in p))
    return abs(p[-1].numerator * (L // p[-1].denominator))


def interval(p, l, h):
    lo = hi = Q(0)
    for x in reversed(p):
        values = (lo * l, lo * h, hi * l, hi * h)
        lo, hi = min(values) + x, max(values) + x
    return lo - (h - l), hi + (h - l)


def fmt(q):
    k = (200 * abs(q.numerator) + q.denominator) // (2 * q.denominator)
    return ("-" if q < 0 and k else "") + f"{k // 100}.{k % 100:02d}"


it = iter(sys.stdin.read().split())
n = int(next(it))
f = list(reversed([Q(next(it)) for _ in range(n + 1)]))
a, b = Q(next(it)), Q(next(it))
a, b = min(a, b), max(a, b)
trim(f)
F = [Q(0)] + [x / (i + 1) for i, x in enumerate(f)]
if a == b or f == [0]:
    print("0.00")
    sys.exit()
sf = squarefree(f)
p = sf
if ev(p, a) == 0:
    p = divmodpoly(p, [-a, Q(1)])[0]
if ev(p, b) == 0:
    p = divmodpoly(p, [-b, Q(1)])[0]
S = sturm(p)
bounds = []
stack = [(a, b)]
while stack:
    l, h = stack.pop()
    count = roots(S, l, h)
    if count == 0:
        continue
    if count == 1:
        bounds.append([l, h])
        continue
    mid = (l + h) / 2
    if ev(p, mid) == 0:
        bounds.append([mid, mid])
    stack.extend(((l, mid), (mid, h)))
bounds.sort()
m = len(bounds)
if m == 0:
    print(fmt(abs(ev(F, b) - ev(F, a))))
    sys.exit()
Bf = denbound(p)
R = valuepoly(sf, F)
RS = sturm(R)
BR = denbound(R)
values = [None] * m
coeff = None
iteration = 0
AP = None
while True:
    for i, (l, h) in enumerate(bounds):
        if l == h:
            values[i] = ev(F, l)
            continue
        candidate = ((l + h) / 2).limit_denominator(Bf)
        if l < candidate < h and ev(p, candidate) == 0:
            bounds[i] = [candidate, candidate]
            values[i] = ev(F, candidate)
            continue
        mid = (l + h) / 2
        if ev(p, mid) == 0:
            bounds[i] = [mid, mid]
            values[i] = ev(F, mid)
        elif roots(S, l, mid):
            bounds[i][1] = mid
        else:
            bounds[i][0] = mid
    if coeff is None:
        signs = []
        for i in range(m + 1):
            l = bounds[i - 1][1] if i else a
            h = bounds[i][0] if i < m else b
            v = ev(f, (l + h) / 2)
            if v == 0:
                break
            signs.append(1 if v > 0 else -1)
        if len(signs) < m + 1:
            continue
        constant = signs[-1] * ev(F, b) - signs[0] * ev(F, a)
        coeff = [signs[i] - signs[i + 1] for i in range(m)]
    lo = hi = exact = constant
    unknown = []
    for i, c in enumerate(coeff):
        if c == 0:
            continue
        if values[i] is not None:
            l = h = values[i]
        else:
            l, h = interval(F, *bounds[i])
            candidate = ((l + h) / 2).limit_denominator(BR)
            if (
                l < candidate < h
                and ev(R, candidate) == 0
                and ev(R, l) != 0
                and ev(R, h) != 0
                and roots(RS, l, h) == 1
            ):
                values[i] = candidate
                l = h = candidate
        if values[i] is not None:
            exact += c * values[i]
        else:
            unknown.append(i)
        lo += c * (l if c > 0 else h)
        hi += c * (h if c > 0 else l)
    lo = max(lo, Q(0))
    if fmt(lo) == fmt(hi):
        print(fmt(lo))
        break
    iteration += 1
    if iteration >= 256 and AP is None:
        offset = exact
        AP = [Q(0), Q(1)]
        for i in unknown:
            AP = sumpoly(AP, linear(R, Q(1, coeff[i]), Q(0)))
        AS = sturm(AP)
    if AP is not None:
        k = (lo * 100).__floor__()
        target = Q(2 * k + 1, 200)
